package com.des;

/**
 * A single job in the queueing scenario.
 */
public final class Job {
    public final String id;
    public final int arrivalTime;
    public final int serviceDuration;

    /** Set when a START_SERVICE event for this job is processed. -1 until then. */
    public int serviceStartTime = -1;
    /** Set when a DEPART event for this job is processed. -1 until then. */
    public int departureTime = -1;
    /** Index of the server that served this job. -1 until assigned. */
    public int server = -1;

    public Job(String id, int arrivalTime, int serviceDuration) {
        this.id = id;
        this.arrivalTime = arrivalTime;
        this.serviceDuration = serviceDuration;
    }

    public int wait() {
        return serviceStartTime - arrivalTime;
    }

    public int turnaround() {
        return departureTime - arrivalTime;
    }
}

package com.des;

/**
 * Event-type priority (used for tie-breaking events that share the same
 * simulation time): DEPART before START_SERVICE before ARRIVE.
 */
public enum EventType {
    DEPART(0),
    START_SERVICE(1),
    ARRIVE(2);

    public final int priority;

    EventType(int priority) {
        this.priority = priority;
    }
}

package com.des;

import com.badlogic.gdx.utils.BinaryHeap;

/**
 * A node scheduled into the libGDX {@link BinaryHeap}. The heap orders nodes
 * purely by the (float) {@code value}, which we set to the integer
 * simulation time of the event. Because the heap's key space is a single
 * float, it alone cannot express the full (time, type-priority, sequence)
 * ordering demanded by the spec. We therefore use the heap strictly for
 * primary (time) ordering -- every event, without exception, is pushed and
 * popped through it -- and resolve ties between events that share the same
 * time using the {@link #type} priority and {@link #seq} fields, which are
 * carried alongside the heap key on this node.
 */
public final class EventNode extends BinaryHeap.Node {
    public final int time;
    public final EventType type;
    public final Job job;
    public final int server;
    public final int seq;

    public EventNode(int time, EventType type, Job job, int server, int seq) {
        super((float) time);
        this.time = time;
        this.type = type;
        this.job = job;
        this.server = server;
        this.seq = seq;
    }
}

package com.des;

import java.util.List;

public final class Scenario {
    public final int numServers;
    public final String discipline; // "FIFO" or "SJF"
    public final List<Job> jobs; // in file order

    public Scenario(int numServers, String discipline, List<Job> jobs) {
        this.numServers = numServers;
        this.discipline = discipline;
        this.jobs = jobs;
    }
}

package com.des;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Parses a scenario description text file into a {@link Scenario}.
 */
public final class ScenarioParser {

    private ScenarioParser() {
    }

    public static Scenario parse(Path path) throws IOException {
        List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);

        List<String[]> nonBlank = new ArrayList<>();
        for (String rawLine : lines) {
            String line = rawLine.trim();
            if (line.isEmpty()) {
                continue;
            }
            String[] tokens = line.split("\\s+");
            nonBlank.add(tokens);
        }

        if (nonBlank.size() < 2) {
            throw new IllegalArgumentException("Scenario file must contain at least the 'servers' and 'discipline' lines");
        }

        String[] serversLine = nonBlank.get(0);
        if (serversLine.length != 2 || !serversLine[0].equals("servers")) {
            throw new IllegalArgumentException("Expected line 1 to be: servers <N>");
        }
        int numServers = Integer.parseInt(serversLine[1]);
        if (numServers < 1) {
            throw new IllegalArgumentException("Number of servers must be >= 1");
        }

        String[] disciplineLine = nonBlank.get(1);
        if (disciplineLine.length != 2 || !disciplineLine[0].equals("discipline")) {
            throw new IllegalArgumentException("Expected line 2 to be: discipline <FIFO|SJF>");
        }
        String discipline = disciplineLine[1];
        if (!discipline.equals("FIFO") && !discipline.equals("SJF")) {
            throw new IllegalArgumentException("Discipline must be FIFO or SJF, got: " + discipline);
        }

        List<Job> jobs = new ArrayList<>();
        Set<String> seenIds = new LinkedHashSet<>();
        for (int i = 2; i < nonBlank.size(); i++) {
            String[] tokens = nonBlank.get(i);
            if (tokens.length != 3) {
                throw new IllegalArgumentException("Expected job line: <jobId> <arrivalTime> <serviceDuration>, got: "
                        + String.join(" ", tokens));
            }
            String jobId = tokens[0];
            if (!jobId.matches("[A-Za-z0-9_]+")) {
                throw new IllegalArgumentException("Invalid jobId: " + jobId);
            }
            if (!seenIds.add(jobId)) {
                throw new IllegalArgumentException("Duplicate jobId: " + jobId);
            }
            int arrivalTime = Integer.parseInt(tokens[1]);
            int serviceDuration = Integer.parseInt(tokens[2]);
            if (arrivalTime < 0) {
                throw new IllegalArgumentException("arrivalTime must be >= 0 for job " + jobId);
            }
            if (serviceDuration < 1) {
                throw new IllegalArgumentException("serviceDuration must be >= 1 for job " + jobId);
            }
            jobs.add(new Job(jobId, arrivalTime, serviceDuration));
        }

        return new Scenario(numServers, discipline, jobs);
    }
}

package com.des;

import com.badlogic.gdx.utils.BinaryHeap;

import java.util.ArrayList;
import java.util.List;

/**
 * Deterministic discrete-event simulation of a multi-server queue.
 *
 * <p>All events are scheduled into a libGDX {@link BinaryHeap} keyed on the
 * (float) simulation time. Every push and every pop of an event goes through
 * this heap. Because the heap's ordering key is a single float, same-time
 * ties (e.g. simultaneous arrivals, or a START_SERVICE event generated
 * reactively at the very instant it is scheduled) are resolved using an
 * explicit event-type priority and a monotonically increasing insertion
 * sequence number, exactly as required by the ordering rules. This
 * resolution never bypasses the heap: nodes are always popped out of the
 * heap first, then staged into per-time-instant buckets purely to apply the
 * secondary/tertiary tie-break before being handed back to the caller.
 *
 * <p>The engine is driven one event at a time via {@link #step()}, which is
 * intended to be called once per tick of the libGDX headless application's
 * render loop.
 */
public final class Simulation {

    private final Scenario scenario;
    private final boolean fifo;

    private final BinaryHeap<EventNode> heap = new BinaryHeap<>();
    private int seq = 0;

    private final boolean[] serverBusy;
    private final List<Job> waiting = new ArrayList<>();

    // Same-instant tie-break staging buckets.
    private Integer batchTime = null;
    private final List<EventNode> departBucket = new ArrayList<>();
    private final List<EventNode> startBucket = new ArrayList<>();
    private final List<EventNode> arriveBucket = new ArrayList<>();

    private final List<String> transcript = new ArrayList<>();
    private int maxQueue = 0;
    private int lastDepartTime = 0;
    private boolean started = false;
    private boolean finished = false;

    public Simulation(Scenario scenario) {
        this.scenario = scenario;
        this.fifo = scenario.discipline.equals("FIFO");
        this.serverBusy = new boolean[scenario.numServers];
    }

    private void ensureStarted() {
        if (started) {
            return;
        }
        started = true;
        // Initial ARRIVE events are pushed once, up front, in file order.
        for (Job job : scenario.jobs) {
            push(EventType.ARRIVE, job, -1, job.arrivalTime);
        }
    }

    private void push(EventType type, Job job, int server, int time) {
        EventNode node = new EventNode(time, type, job, server, seq);
        seq++;
        heap.add(node, (float) time);
    }

    /** Pulls any newly-available nodes at the current batch time out of the heap into buckets. */
    private void refill() {
        if (batchTime == null) {
            return;
        }
        int t = batchTime;
        while (heap.notEmpty() && heap.peek().time == t) {
            EventNode node = heap.pop();
            switch (node.type) {
                case DEPART:
                    departBucket.add(node);
                    break;
                case START_SERVICE:
                    startBucket.add(node);
                    break;
                case ARRIVE:
                    arriveBucket.add(node);
                    break;
            }
        }
    }

    private static EventNode pollLowestSeq(List<EventNode> bucket) {
        int minIdx = 0;
        for (int i = 1; i < bucket.size(); i++) {
            if (bucket.get(i).seq < bucket.get(minIdx).seq) {
                minIdx = i;
            }
        }
        return bucket.remove(minIdx);
    }

    /** Returns the next event to process in strict order, or null if the simulation is complete. */
    private EventNode nextEvent() {
        while (true) {
            refill();
            if (!departBucket.isEmpty()) {
                return pollLowestSeq(departBucket);
            }
            if (!startBucket.isEmpty()) {
                return pollLowestSeq(startBucket);
            }
            if (!arriveBucket.isEmpty()) {
                return pollLowestSeq(arriveBucket);
            }
            if (heap.isEmpty()) {
                batchTime = null;
                return null;
            }
            batchTime = heap.peek().time;
        }
    }

    /**
     * Advances the simulation by exactly one event. Intended to be called
     * once per render-loop tick.
     *
     * @return true if an event was processed, false if the simulation had
     *         already completed (nothing left to do).
     */
    public boolean step() {
        ensureStarted();
        if (finished) {
            return false;
        }
        EventNode node = nextEvent();
        if (node == null) {
            finished = true;
            return false;
        }
        process(node);
        return true;
    }

    public boolean isFinished() {
        return finished;
    }

    private void process(EventNode node) {
        switch (node.type) {
            case ARRIVE:
                transcript.add("t " + node.time + " ARRIVE " + node.job.id);
                waiting.add(node.job);
                if (waiting.size() > maxQueue) {
                    maxQueue = waiting.size();
                }
                dispatch(node.time);
                break;
            case START_SERVICE:
                transcript.add("t " + node.time + " START_SERVICE " + node.job.id + " server " + node.server);
                node.job.serviceStartTime = node.time;
                node.job.server = node.server;
                push(EventType.DEPART, node.job, node.server, node.time + node.job.serviceDuration);
                break;
            case DEPART:
                transcript.add("t " + node.time + " DEPART " + node.job.id + " server " + node.server);
                node.job.departureTime = node.time;
                serverBusy[node.server] = false;
                if (node.time > lastDepartTime) {
                    lastDepartTime = node.time;
                }
                dispatch(node.time);
                break;
        }
    }

    private void dispatch(int time) {
        while (true) {
            int serverIdx = -1;
            for (int i = 0; i < serverBusy.length; i++) {
                if (!serverBusy[i]) {
                    serverIdx = i;
                    break;
                }
            }
            if (serverIdx == -1 || waiting.isEmpty()) {
                break;
            }

            int jobIdx;
            if (fifo) {
                jobIdx = 0;
            } else {
                jobIdx = 0;
                for (int i = 1; i < waiting.size(); i++) {
                    if (waiting.get(i).serviceDuration < waiting.get(jobIdx).serviceDuration) {
                        jobIdx = i;
                    }
                }
            }

            Job job = waiting.remove(jobIdx);
            serverBusy[serverIdx] = true;
            push(EventType.START_SERVICE, job, serverIdx, time);
        }
    }

    public List<String> getTranscript() {
        return transcript;
    }

    public int getMaxQueue() {
        return maxQueue;
    }

    public int getLastDepartTime() {
        return lastDepartTime;
    }

    public Scenario getScenario() {
        return scenario;
    }
}

package com.des;

import java.io.IOException;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

public final class ReportWriter {

    private ReportWriter() {
    }

    public static void write(Simulation sim, Path outPath) throws IOException {
        Scenario scenario = sim.getScenario();
        StringBuilder sb = new StringBuilder();

        sb.append("TRANSCRIPT\n");
        for (String line : sim.getTranscript()) {
            sb.append(line).append('\n');
        }

        sb.append("METRICS\n");
        for (Job job : scenario.jobs) {
            sb.append("job ").append(job.id)
                    .append(" wait ").append(job.wait())
                    .append(" turnaround ").append(job.turnaround())
                    .append('\n');
        }

        sb.append("STATS\n");

        long waitSum = 0;
        for (Job job : scenario.jobs) {
            waitSum += job.wait();
        }
        int numJobs = scenario.jobs.size();
        String meanWait = numJobs == 0 ? "0.000" : formatRatio(waitSum, numJobs);
        sb.append("mean_wait ").append(meanWait).append('\n');
        sb.append("max_queue ").append(sim.getMaxQueue()).append('\n');

        long[] busyTime = new long[scenario.numServers];
        for (Job job : scenario.jobs) {
            if (job.server >= 0) {
                busyTime[job.server] += (long) (job.departureTime - job.serviceStartTime);
            }
        }
        int endTime = sim.getLastDepartTime();
        for (int i = 0; i < scenario.numServers; i++) {
            String utilization = endTime == 0 ? "0.000" : formatRatio(busyTime[i], endTime);
            sb.append("server ").append(i).append(" utilization ").append(utilization).append('\n');
        }

        Path parent = outPath.toAbsolutePath().getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }
        Files.write(outPath, sb.toString().getBytes(StandardCharsets.UTF_8));
    }

    private static String formatRatio(long numerator, long denominator) {
        BigDecimal bd = new BigDecimal(numerator)
                .divide(new BigDecimal(denominator), 3, RoundingMode.HALF_UP);
        return bd.toPlainString();
    }
}

