import java.util.concurrent.atomic.AtomicReference;

/**
 * Drives the {@link Simulation} from the headless application's render/tick
 * loop: exactly one event is processed per {@link #render()} call. Once the
 * event heap is drained, the report is written and the application exits.
 */
public final class SimulationListener implements ApplicationListener {

    private final Path scenarioPath;
    private final Path outPath;
    private final CountDownLatch doneLatch;
    private final AtomicReference<Throwable> failure;

    private Simulation simulation;

    public SimulationListener(Path scenarioPath, Path outPath, CountDownLatch doneLatch, AtomicReference<Throwable> failure) {
        this.scenarioPath = scenarioPath;
        this.outPath = outPath;
        this.doneLatch = doneLatch;
        this.failure = failure;
    }

    @Override
    public void create() {
        try {
            Scenario scenario = ScenarioParser.parse(scenarioPath);
            simulation = new Simulation(scenario);
        } catch (Throwable t) {
            failure.set(t);
            Gdx.app.exit();
        }
    }

    @Override
    public void render() {
        if (simulation == null) {
            // create() already failed; nothing to do but wait for exit to take effect.
            return;
        }
        try {
            if (simulation.isFinished()) {
                return;
            }
            boolean progressed = simulation.step();
            if (!progressed || simulation.isFinished()) {
                ReportWriter.write(simulation, outPath);
                Gdx.app.exit();
            }
        } catch (Throwable t) {
            failure.set(t);
            Gdx.app.exit();
        }
    }

    @Override
    public void resize(int width, int height) {
        // no-op: headless, no rendering surface
    }

    @Override
    public void pause() {
        // no-op
    }

    @Override
    public void resume() {
        // no-op
    }

    @Override
    public void dispose() {
        doneLatch.countDown();
    }
}

package com.des;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Entry point. Usage:
 *   run.sh --scenario <scenarioPath> --out <outPath>
 *
 * Runs the deterministic discrete-event simulation inside a libGDX
 * HeadlessApplication, driven entirely by its render/tick loop.
 */
public final class Main {

    public static void main(String[] args) {
        String scenarioArg = null;
        String outArg = null;

        for (int i = 0; i < args.length; i++) {
            switch (args[i]) {
                case "--scenario":
                    if (i + 1 >= args.length) {
                        fail("Missing value for --scenario");
                    }
                    scenarioArg = args[++i];
                    break;
                case "--out":
                    if (i + 1 >= args.length) {
                        fail("Missing value for --out");
                    }
                    outArg = args[++i];
                    break;
                default:
                    fail("Unrecognized argument: " + args[i]);
            }
        }

        if (scenarioArg == null || outArg == null) {
            fail("Usage: run.sh --scenario <scenarioPath> --out <outPath>");
        }

        Path scenarioPath = Paths.get(scenarioArg);
        Path outPath = Paths.get(outArg);

        CountDownLatch doneLatch = new CountDownLatch(1);
        AtomicReference<Throwable> failure = new AtomicReference<>();

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Run the tick loop as fast as possible (no throttling / sleeping);
        // the loop still calls render() repeatedly, which is what drives the
        // simulation forward one event at a time.
        config.updatesPerSecond = 0;

        SimulationListener listener = new SimulationListener(scenarioPath, outPath, doneLatch, failure);
        new HeadlessApplication(listener, config);

        try {
            doneLatch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        Throwable t = failure.get();
        if (t != null) {
            System.err.println("Simulation failed: " + t.getMessage());
            t.printStackTrace();
            System.exit(1);
        }
        System.exit(0);
    }

    private static void fail(String message) {
        System.err.println(message);
        System.exit(2);
        throw new AssertionError("unreachable");
    }
}
